package it.unicam.cs.mpgc.rpg124913.entities.core;

/**
 * Defines the capability of an entity to act as an offensive threat.
 * Isolating this behavior enables the creation of entities that deal damage but cannot
 * be attacked themselves, such as environmental hazards (e.g., toxic fog or spike traps).
 */
public interface DamageDealer {

    /**
     * Computes the base damage output generated by the entity.
     *
     * @return The numerical value of the offensive power.
     */
    int damageOutput();
}